/** The stream ended before the requested data arrived. */
export class IncompleteReadError extends Error {
  readonly partial: Buffer;

  constructor(partial: Buffer) {
    super(`stream ended after ${partial.length} bytes`);
    this.name = "IncompleteReadError";
    this.partial = partial;
  }
}

/** A separator was not found within the allowed number of bytes. */
export class LimitOverrunError extends Error {
  constructor(limit: number) {
    super(`separator not found within ${limit} bytes`);
    this.name = "LimitOverrunError";
  }
}

const EMPTY = Buffer.alloc(0);

/**
 * Pull-based buffered reader over a socket. The socket is kept paused except
 * while the reader is waiting for more data, so a slow consumer applies
 * backpressure instead of buffering unbounded input.
 */
export class StreamReader {
  readonly #socket: Socket;
  #buffer: Buffer = EMPTY;
  #ended = false;
  #error: Error | undefined;
  #wake: (() => void) | undefined;

  constructor(socket: Socket) {
    this.#socket = socket;
    socket.pause();
    socket.on("data", (chunk: Buffer) => {
      this.#buffer = this.#buffer.length === 0 ? chunk : Buffer.concat([this.#buffer, chunk]);
      socket.pause();
      this.#notify();
    });
    socket.on("end", () => {
      this.#ended = true;
      this.#notify();
    });
    socket.on("error", (err) => {
      this.#error = err;
      this.#notify();
    });
  }

  /** Reads up to and including `separator`, which must appear within `limit` bytes. */
  async readUntil(separator: Buffer, limit: number): Promise<Buffer> {
    let searchFrom = 0;
    for (;;) {
      const index = this.#buffer.indexOf(separator, searchFrom);
      if (index >= 0) {
        const end = index + separator.length;
        if (end > limit) throw new LimitOverrunError(limit);
        return this.#take(end);
      }
      if (this.#buffer.length > limit) throw new LimitOverrunError(limit);
      searchFrom = Math.max(0, this.#buffer.length - separator.length + 1);
      if (!(await this.#fill())) throw new IncompleteReadError(this.#take(this.#buffer.length));
    }
  }

  /** Reads exactly `n` bytes. */
  async readExactly(n: number): Promise<Buffer> {
    const parts: Buffer[] = [];
    let remaining = n;
    while (remaining > 0) {
      if (this.#buffer.length === 0 && !(await this.#fill())) {
        throw new IncompleteReadError(Buffer.concat(parts));
      }
      const part = this.#take(Math.min(remaining, this.#buffer.length));
      parts.push(part);
      remaining -= part.length;
    }
    return parts.length === 1 ? parts[0]! : Buffer.concat(parts, n);
  }

  /** Reads and drops exactly `n` bytes. */
  async discard(n: number): Promise<void> {
    let remaining = n;
    while (remaining > 0) {
      if (this.#buffer.length === 0 && !(await this.#fill())) {
        throw new IncompleteReadError(EMPTY);
      }
      remaining -= this.#take(Math.min(remaining, this.#buffer.length)).length;
    }
  }

  #take(n: number): Buffer {
    const out = this.#buffer.subarray(0, n);
    this.#buffer = this.#buffer.subarray(n);
    return out;
  }

  /** Waits for more input; resolves false at end of stream. */
  async #fill(): Promise<boolean> {
    const before = this.#buffer.length;
    while (this.#buffer.length === before) {
      if (this.#error) throw this.#error;
      if (this.#ended) return false;
      await new Promise<void>((resolve) => {
        this.#wake = resolve;
        this.#socket.resume();
      });
    }
    return true;
  }

  #notify(): void {
    const wake = this.#wake;
    this.#wake = undefined;
    wake?.();
  }
}

import net from "node:net";
import type { App } from "./app.ts";
import { HttpError, type Response, serializeResponse } from "./http.ts";
import { readRequest } from "./parser.ts";
import { StreamReader } from "./reader.ts";

/** Serves one request per connection, then closes it. */
export class Server {
  readonly #app: App;

  constructor(app: App) {
    this.#app = app;
  }

  listen(host: string, port: number): Promise<net.Server> {
    const server = net.createServer({ allowHalfOpen: true }, (socket) => void this.#handleConnection(socket));
    return new Promise((resolve, reject) => {
      server.once("error", reject);
      server.listen({ host, port, backlog: 1024 }, () => {
        server.off("error", reject);
        resolve(server);
      });
    });
  }

  async #handleConnection(socket: net.Socket): Promise<void> {
    const reader = new StreamReader(socket);
    try {
      let response: Response;
      try {
        const request = await readRequest(reader);
        if (request === null) return;
        response = this.#app.handle(request);
      } catch (err) {
        if (!(err instanceof HttpError)) throw err;
        response = { status: err.status };
      }
      await write(socket, serializeResponse(response));
    } catch (err) {
      if (!isConnectionError(err)) console.error("unhandled error while serving request:", err);
    } finally {
      socket.destroy();
    }
  }
}

/** Writes and flushes the data, then half-closes the socket. */
function write(socket: net.Socket, data: Buffer): Promise<void> {
  return new Promise((resolve, reject) => {
    socket.end(data, () => resolve());
    socket.once("error", reject);
  });
}

function isConnectionError(err: unknown): boolean {
  return err instanceof Error && "code" in err && typeof err.code === "string";
}

/** In-memory key-value store. Node is single-threaded, so no locking is needed. */
export class Store {
  readonly #data = new Map<string, Buffer>();

  /** Stores the value; returns true if the key was new. */
  put(key: string, value: Buffer): boolean {
    const created = !this.#data.has(key);
    this.#data.set(key, value);
    return created;
  }

  get(key: string): Buffer | undefined {
    return this.#data.get(key);
  }

  delete(key: string): boolean {
    return this.#data.delete(key);
  }

  /** All keys, sorted ascending. Keys are ASCII, so code-unit order is byte order. */
  keys(): string[] {
    return [...this.#data.keys()].sort();
  }
}
